solution.solution.cpp:
#include <string>

struct Range { int low; int high; };
using BinaryOp = int (*)(int, int);
using Predicate = bool (*)(int value, void* context);

static int add(int a, int b) { return a + b; }
static int sub(int a, int b) { return a - b; }
static int mul(int a, int b) { return a * b; }
static int largest(int a, int b) { return a > b ? a : b; }
static int smallest(int a, int b) { return a < b ? a : b; }

BinaryOp lookup(const std::string& name)
{
    struct Entry { const char* name; BinaryOp op; };
    static const Entry table[]{ { "add", add }, { "sub", sub }, { "mul", mul }, { "max", largest }, { "min", smallest } };
    for (const Entry& e : table)
        if (name == e.name) return e.op;
    return nullptr;
}

int fold(const int* values, int count, int start, BinaryOp op)
{
    int result{ start };
    for (int i{ 0 }; i < count; ++i) result = op(result, values[i]);
    return result;
}

int countIf(const int* values, int count, Predicate test, void* context)
{
    int n{ 0 };
    for (int i{ 0 }; i < count; ++i)
        if (test(values[i], context)) ++n;
    return n;
}

bool inRange(int value, void* context)
{
    const Range* r{ static_cast<const Range*>(context) };
    return value >= r->low && value <= r->high;
}

unitTests:
TEST("lookup") {
    CHECK(lookup("add") != nullptr);
    CHECK_EQ(lookup("add")(2, 3), 5);
    CHECK_EQ(lookup("sub")(2, 3), -1);
    CHECK_EQ(lookup("mul")(4, 5), 20);
    CHECK_EQ(lookup("max")(4, 9), 9);
    CHECK_EQ(lookup("min")(4, 9), 4);
    CHECK(lookup("pow") == nullptr);
    CHECK(lookup("") == nullptr);
}
TEST("fold") {
    const int v[]{ 3, 1, 4, 1, 5 };
    CHECK_EQ(fold(v, 5, 0, lookup("add")), 14);
    CHECK_EQ(fold(v, 5, 1, lookup("mul")), 60);
    CHECK_EQ(fold(v, 5, 100, lookup("sub")), 86);
    CHECK_EQ(fold(v, 5, -1000, lookup("max")), 5);
    CHECK_EQ(fold(v, 0, 7, lookup("add")), 7);
}
static bool isEven(int value, void*) { return value % 2 == 0; }
static bool countCalls(int, void* context) { ++*static_cast<int*>(context); return true; }
TEST("countIf with a context") {
    const int v[]{ 5, 12, 7, 30, 18, -2 };
    Range teens{ 13, 19 };
    CHECK_EQ(countIf(v, 6, inRange, &teens), 1);
    Range wide{ 0, 100 };
    CHECK_EQ(countIf(v, 6, inRange, &wide), 5);
    CHECK_EQ(countIf(v, 6, isEven, nullptr), 4);
    int calls{ 0 };
    CHECK_EQ(countIf(v, 6, countCalls, &calls), 6);
    CHECK_EQ(calls, 6);
}

